'use client'

import { SilkBorder, SILK_PRESETS, type SilkPreset } from '@/components/spaceui/silk-border'
import { Squishmoji } from '@usespaceui/squishmoji/react'

const PRESETS = Object.keys(SILK_PRESETS) as SilkPreset[]

export default function Demo() {
  return (
    <div className="flex flex-wrap items-center justify-center gap-6 p-6">
      {PRESETS.map((preset) => (
        <SilkBorder key={preset} preset={preset} className="inline-flex size-16 rounded-full p-0.75">
          <Squishmoji
            seed={preset}
            shape="all"
            expression="all"
            backgroundStyle="all"
            size={56}
            animate
            animWobble
            animOnHover
            animOnClick
          />
        </SilkBorder>
      ))}
    </div>
  )
}
